#include <bits/stdc++.h>
using namespace std;

int countColors(const vector<int>& arr, int start, int end) {
    bool visited[24] = {false};
    int count = 0;
    for (int i = start; i <= end; i++) {
        int color = arr[i];
        if (!visited[color]) {
            visited[color] = true;
            count++;
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    l -= 1;
    r -= 1;
    int total = a + b;
    int repeats = 4;
    vector<int> pattern(total * repeats);
    int shiftH = l / total;
    l -= shiftH * total;
    r -= shiftH * total;
    int segmentCount = (r - l + 1) / total;
    if (segmentCount > 2) r -= (segmentCount - 2) * total;
    int diff = max(a - b, 1);
    for (int rep = 0; rep < repeats; rep++) {
        for (int k = 0; k < a - diff; k++)
            pattern[total * rep + k] = k;
        for (int k = 0; k < diff; k++)
            pattern[total * rep + a - diff + k] = (rep % 2 == 0) ? a - diff + k : a + k;
    }
    int minColorsCount = a + a;
    for (int shiftAIdx = 1; shiftAIdx <= diff; shiftAIdx++) {
        for (int k = 0; k < b; k++)
            pattern[a + k] = pattern[a - shiftAIdx];
        for (int shiftBIdx1 = 1; shiftBIdx1 <= diff; shiftBIdx1++) {
            for (int k = 0; k < b; k++)
                pattern[total + a + k] = pattern[total + a - shiftBIdx1];
            for (int shiftBIdx2 = 1; shiftBIdx2 <= diff; shiftBIdx2++) {
                for (int k = 0; k < b; k++)
                    pattern[2 * total + a + k] = pattern[2 * total + a - shiftBIdx2];
                for (int shiftBIdx3 = 1; shiftBIdx3 <= diff; shiftBIdx3++) {
                    for (int k = 0; k < b; k++)
                        pattern[3 * total + a + k] = pattern[3 * total + a - shiftBIdx3];
                    minColorsCount = min(minColorsCount, countColors(pattern, l, r));
                }
            }
        }
    }
    cout << minColorsCount << "\n";
    return 0;
}

